<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api'
import { parseStudentPaste } from '../review-utils'
const classes=ref<any[]>([]),drawer=ref(false),selected=ref<any>(null),text=ref(''),members=ref<any[]>([]),result=ref<any>(null),loading=ref(false)
const props=withDefaults(defineProps<{courseId?:string;termId?:string}>(),{courseId:'',termId:''})
const visibleClasses=computed(()=>classes.value.filter(row=>(!props.courseId||row.course_id===props.courseId)&&(!props.termId||row.term_id===props.termId)))
const classLabel=(row:any)=>`${row.course_name} · ${row.class_name}（${row.member_count||0}人）`
watch(visibleClasses,()=>{if(selected.value&&!visibleClasses.value.some(row=>row.class_id===selected.value.class_id)){selected.value=null;drawer.value=false}})
const statusLabels:Record<string,string>={created:'已创建',reused:'已复用',already_member:'已在本班',conflict:'冲突',invalid:'格式无效',active:'在班',inactive:'已停用',removed:'已移除'}
const passwordOpen=ref(false),passwordStudent=ref<any>(null),newPassword=ref(''),confirmPassword=ref(''),resetting=ref(false)
async function load(){const classResult=await api.get('/teacher/classes',{params:{_refresh:Date.now()},headers:{'Cache-Control':'no-cache'}});classes.value=classResult.data;if(selected.value)selected.value=classes.value.find(row=>row.class_id===selected.value.class_id)||null}
async function open(){if(!selected.value)return;drawer.value=true;result.value=null;members.value=(await api.get(`/teacher/classes/${selected.value.class_id}/members`)).data}
function parsed(){return parseStudentPaste(text.value)}
function showImportResult(){ElMessage.success(Number(result.value?.summary?.created)>0?'名单处理完成；新建学生账号的初始密码为各自学号，首次登录需修改密码。':'名单处理完成；已有账号密码保持不变。')}
async function paste(){loading.value=true;try{result.value=(await api.post(`/teacher/classes/${selected.value.class_id}/members/import`,{students:parsed()})).data;members.value=result.value.members;text.value='';await load();showImportResult()}catch(e:any){ElMessage.error(e.response?.data?.detail||'导入失败')}finally{loading.value=false}}
async function fileImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const form=new FormData();form.append('file',file);loading.value=true;try{result.value=(await api.post(`/teacher/classes/${selected.value.class_id}/members/import-file`,form)).data;members.value=result.value.members;await load();showImportResult()}catch(e:any){ElMessage.error(e.response?.data?.detail||'文件导入失败')}finally{loading.value=false;input.value=''}}
function openPassword(row:any){passwordStudent.value=row;newPassword.value='';confirmPassword.value='';passwordOpen.value=true}
async function resetPassword(){if(newPassword.value.length<10)return ElMessage.warning('新密码至少需要 10 个字符');if(newPassword.value!==confirmPassword.value)return ElMessage.warning('两次输入的密码不一致');resetting.value=true;try{await api.post(`/teacher/classes/${selected.value.class_id}/members/${passwordStudent.value.user_id}/reset-password`,{new_password:newPassword.value});passwordOpen.value=false;members.value=(await api.get(`/teacher/classes/${selected.value.class_id}/members`)).data;ElMessage.success('学生密码已重置；其下次登录必须设置个人密码')}catch(e:any){ElMessage.error(e.response?.data?.detail||'密码重置失败')}finally{resetting.value=false}}
async function refresh(){await load().catch(()=>undefined)};defineExpose({refresh});onMounted(()=>load().catch(()=>undefined))
</script>
<template>
  <section class="member-console workbench-panel">
    <div><b>教学班成员管理</b><small>同一学号共用一个账号，可加入多个课程教学班</small></div>
    <el-select v-model="selected" value-key="class_id" placeholder="选择课程与教学班" aria-label="选择课程与教学班" filterable>
      <el-option v-for="row in visibleClasses" :key="row.class_id" :label="classLabel(row)" :value="row"/>
    </el-select>
    <el-button type="primary" :disabled="!selected" @click="open">打开成员工作台</el-button>
  </section>
  <el-drawer v-model="drawer" size="min(860px,96vw)" :title="`${selected?.course_name||''} · ${selected?.class_name||''} · 学生与账号`"><el-alert title="新导入学生的初始密码为本人学号" description="学生使用学号登录，首次登录需修改密码。重复导入或跨班复用已有账号时保留原密码，课程任务和成绩按教学班分别保存。" type="info" :closable="false"/><el-tabs><el-tab-pane label="粘贴名单"><p class="muted">学号为 6–20 位数字，保留前导零；同一学号复用账号，重复导入不会新增成员。每行一个学号，或“学号,姓名”“学号⇥姓名”，最多 5000 行。</p><el-input v-model="text" type="textarea" :rows="8" placeholder="20260001,张三&#10;20260002,李四"/><el-button class="member-import-button" type="primary" :loading="loading" :disabled="!text.trim()" @click="paste">导入名单</el-button></el-tab-pane><el-tab-pane label="CSV / XLSX"><p class="muted">必需列：学号/student_number（6–20 位数字，请设为文本以保留前导零）；可选列：姓名/display_name。</p><label class="file-picker"><input type="file" accept=".csv,.xlsx" @change="fileImport"/>选择名单文件</label></el-tab-pane></el-tabs><el-descriptions v-if="result" class="import-summary" :column="5" border><el-descriptions-item v-for="(value,key) in result.summary" :key="key" :label="statusLabels[String(key)]||String(key)">{{value}}</el-descriptions-item></el-descriptions><el-table v-if="result" :data="result.results" max-height="230"><el-table-column prop="row" label="行" width="55"/><el-table-column prop="student_number" label="学号"/><el-table-column prop="display_name" label="姓名"/><el-table-column label="结果"><template #default="s">{{statusLabels[s.row.status]||s.row.status}}</template></el-table-column><el-table-column prop="message" label="说明"/></el-table><h3>现有成员（{{members.length}}）</h3><el-table :data="members"><el-table-column prop="student_number" label="学号" min-width="130"/><el-table-column prop="display_name" label="姓名" min-width="120"/><el-table-column label="已加入的课程教学班" min-width="230"><template #default="s"><div v-for="scope in s.row.joined_classes" :key="scope.class_id" class="joined-class">{{scope.course_name}} · {{scope.class_name}}</div></template></el-table-column><el-table-column label="账号状态" width="130"><template #default="s"><el-tag :type="s.row.must_change_password?'warning':'success'">{{s.row.must_change_password?'待修改密码':'正常'}}</el-tag></template></el-table-column><el-table-column label="成员状态" width="100"><template #default="s">{{statusLabels[s.row.status]||s.row.status}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="s"><el-button link type="primary" @click="openPassword(s.row)">重置密码</el-button></template></el-table-column></el-table></el-drawer>
  <el-dialog v-model="passwordOpen" title="重置学生密码" width="min(520px,92vw)" append-to-body><el-alert type="warning" :closable="false" :title="`正在重置 ${passwordStudent?.display_name||passwordStudent?.student_number} 的密码；该学生现有登录会失效。`"/><el-alert class="password-rule" type="info" :closable="false" title="密码格式：至少 10 个字符；建议同时包含字母、数字和符号。两次输入必须完全一致。"/><el-form label-position="top"><el-form-item label="新临时密码" :error="newPassword&&newPassword.length<10?'还需输入 '+(10-newPassword.length)+' 个字符':''"><el-input v-model="newPassword" type="password" show-password autocomplete="new-password" maxlength="256" show-word-limit/></el-form-item><el-form-item label="再次确认" :error="confirmPassword&&newPassword!==confirmPassword?'两次输入不一致':''"><el-input v-model="confirmPassword" type="password" show-password autocomplete="new-password" maxlength="256" @keyup.enter="resetPassword"/></el-form-item></el-form><template #footer><el-button @click="passwordOpen=false">取消</el-button><el-button type="primary" :loading="resetting" :disabled="newPassword.length<10||newPassword!==confirmPassword" @click="resetPassword">确认重置</el-button></template></el-dialog>
</template>

<style scoped>.member-console{display:grid;grid-template-columns:minmax(220px,1fr) minmax(300px,440px) auto;gap:16px;align-items:center;margin-top:16px;padding:18px}.member-console>div{display:grid;gap:4px}.member-console :deep(.el-select){width:100%}.joined-class{line-height:1.65;overflow-wrap:anywhere}.member-console b{font-size:17px;color:#173e49}.member-console small{color:#71827d}.password-rule{margin:12px 0}@media(max-width:800px){.member-console{grid-template-columns:1fr}}</style>
